    if (u_g.oh_IQSelUop_22_0 | u_g.oh_IQSelUop_22_1 | u_g.oh_IQSelUop_22_2 | u_g.oh_IQSelUop_22_3 | u_g.oh_IQSelUop_22_4 | u_g.oh_IQSelUop_22_5) g_port_used[22] = 1'b1;
    if (|u_i.u_core.oh[22]) i_port_used[22] = 1'b1;
    if (u_g.oh_IQSelUop_23_0 | u_g.oh_IQSelUop_23_1 | u_g.oh_IQSelUop_23_2 | u_g.oh_IQSelUop_23_3 | u_g.oh_IQSelUop_23_4 | u_g.oh_IQSelUop_23_5) g_port_used[23] = 1'b1;
    if (|u_i.u_core.oh[23]) i_port_used[23] = 1'b1;
    if (u_g.oh_IQSelUop_24_0 | u_g.oh_IQSelUop_24_1 | u_g.oh_IQSelUop_24_2 | u_g.oh_IQSelUop_24_3 | u_g.oh_IQSelUop_24_4 | u_g.oh_IQSelUop_24_5) g_port_used[24] = 1'b1;
    if (|u_i.u_core.oh[24]) i_port_used[24] = 1'b1;
    if (u_g.oh_IQSelUop_25_0 | u_g.oh_IQSelUop_25_1 | u_g.oh_IQSelUop_25_2 | u_g.oh_IQSelUop_25_3 | u_g.oh_IQSelUop_25_4 | u_g.oh_IQSelUop_25_5) g_port_used[25] = 1'b1;
    if (|u_i.u_core.oh[25]) i_port_used[25] = 1'b1;
    if (u_g.oh_IQSelUop_26_0 | u_g.oh_IQSelUop_26_1 | u_g.oh_IQSelUop_26_2 | u_g.oh_IQSelUop_26_3 | u_g.oh_IQSelUop_26_4 | u_g.oh_IQSelUop_26_5) g_port_used[26] = 1'b1;
    if (|u_i.u_core.oh[26]) i_port_used[26] = 1'b1;
    if (u_g.oh_IQSelUop_27_0 | u_g.oh_IQSelUop_27_1 | u_g.oh_IQSelUop_27_2 | u_g.oh_IQSelUop_27_3 | u_g.oh_IQSelUop_27_4 | u_g.oh_IQSelUop_27_5) g_port_used[27] = 1'b1;
    if (|u_i.u_core.oh[27]) i_port_used[27] = 1'b1;
    if (u_g.oh_IQSelUop_28_0 | u_g.oh_IQSelUop_28_1 | u_g.oh_IQSelUop_28_2 | u_g.oh_IQSelUop_28_3 | u_g.oh_IQSelUop_28_4 | u_g.oh_IQSelUop_28_5) g_port_used[28] = 1'b1;
    if (|u_i.u_core.oh[28]) i_port_used[28] = 1'b1;
    if (u_g.oh_IQSelUop_29_0 | u_g.oh_IQSelUop_29_1 | u_g.oh_IQSelUop_29_2 | u_g.oh_IQSelUop_29_3 | u_g.oh_IQSelUop_29_4 | u_g.oh_IQSelUop_29_5) g_port_used[29] = 1'b1;
    if (|u_i.u_core.oh[29]) i_port_used[29] = 1'b1;
    if (u_g.oh_IQSelUop_30_0 | u_g.oh_IQSelUop_30_1 | u_g.oh_IQSelUop_30_2 | u_g.oh_IQSelUop_30_3 | u_g.oh_IQSelUop_30_4 | u_g.oh_IQSelUop_30_5) g_port_used[30] = 1'b1;
    if (|u_i.u_core.oh[30]) i_port_used[30] = 1'b1;
    if (u_g.oh_IQSelUop_31_0 | u_g.oh_IQSelUop_31_1 | u_g.oh_IQSelUop_31_2 | u_g.oh_IQSelUop_31_3 | u_g.oh_IQSelUop_31_4 | u_g.oh_IQSelUop_31_5) g_port_used[31] = 1'b1;
    if (|u_i.u_core.oh[31]) i_port_used[31] = 1'b1;
    if (u_g.oh_IQSelUop_32_0 | u_g.oh_IQSelUop_32_1 | u_g.oh_IQSelUop_32_2 | u_g.oh_IQSelUop_32_3 | u_g.oh_IQSelUop_32_4 | u_g.oh_IQSelUop_32_5) g_port_used[32] = 1'b1;
    if (|u_i.u_core.oh[32]) i_port_used[32] = 1'b1;
    if (u_g.oh_IQSelUop_33_0 | u_g.oh_IQSelUop_33_1 | u_g.oh_IQSelUop_33_2 | u_g.oh_IQSelUop_33_3 | u_g.oh_IQSelUop_33_4 | u_g.oh_IQSelUop_33_5) g_port_used[33] = 1'b1;
    if (|u_i.u_core.oh[33]) i_port_used[33] = 1'b1;
  end

  // ---- 逐拍比对 ----
  always @(posedge clk) begin
    cyc++;
    if (!rst && cyc > WARMUP) begin
      checks++;
      for (int k = 0; k < NOUT; k++)
        if (gv[k] !== iv[k]) ever_mm[k] = 1'b1;
    end
  end

  // 判据 D：重写侧每条 lane 的 payload 都必须真的被某个 enq 口选中过，
  // 否则"A 清单外失配=0"里有一大半位置根本没被激励碰到过（MA-3 就是这么漏的）。
  // ★步骤 2 起 D 重新是硬闸★：选择通路已接通，Makefile 里那行
  // +known_hole_frozen_select 已经删掉（放行开关的那句"落地后必须删掉"兑现了）。
  // known_hole 这条路径留着只为让老命令行不报错，正常跑法下它恒为 0。
  int unexpected_red = 0, silent_blocked = 0, blocked_red = 0, clean = 0, unsel_lanes = 0, undetermined = 0;
  bit known_hole = 0;
  initial begin
    if ($value$plusargs("ncycles=%d", NCYCLES));
    known_hole = $test$plusargs("known_hole_frozen_select");
    repeat (8) @(posedge clk);
    rst = 0;
    repeat (NCYCLES) @(posedge clk);
    for (int k = 0; k < NOUT; k++) begin
      if (must_eq[k] && ever_mm[k]) begin
        unexpected_red++;
        if (unexpected_red <= 25) $display("  [A-FAIL] 应恒等的位却失配: %s", pname[k]);
      end else if (must_red[k] && !ever_mm[k]) begin
        silent_blocked++;
        if (silent_blocked <= 25) $display("  [B-FAIL] 悬空位(Z)竟没失配 = tb 漏检: %s", pname[k]);
      end else if (must_eq[k]) clean++;
      else if (must_red[k]) blocked_red++;
      else undetermined++;
    end
    $display("NewDispatch UT: checks=%0d stim_moves=%0d NOUT=%0d", checks, stim_moves, NOUT);
    $display("  A 组 必须恒等(与选择无关的常量) = %0d 位，全部一致", clean);
    $display("  B 组 必须失配(impl 悬空=Z)      = %0d 位，全部如期失配", blocked_red);
    $display("  A 清单外失配               = %0d", unexpected_red);
    $display("  未判定(选择通路冻住，两侧可能巧合相等) = %0d 位", undetermined);
    $display("  A 违反 = %0d   B 违反 = %0d", unexpected_red, silent_blocked);
    for (int l = 0; l < 6; l++) if (i_lane_sel[l] == 0) unsel_lanes++;
    $display("  lane 被选中的拍数 golden/重写:");
    for (int l = 0; l < 6; l++)
      $display("    lane%0d  golden=%0d  重写=%0d%s", l, g_lane_sel[l], i_lane_sel[l],
               (i_lane_sel[l] == 0) ? "   <- 重写侧从没选中，该 lane 的 payload 未被验证" : "");
    if (checks == 0 || stim_moves == 0)
      $display("TEST FAILED: 判据 C —— 根本没比/激励没动");
    else if (unsel_lanes != 0 && !known_hole)
      $display("TEST FAILED: 判据 D —— %0d 条 lane 的 payload 从没被选中过(覆盖洞)", unsel_lanes);
    else if (unexpected_red != 0)
      $display("TEST FAILED: 判据 A —— %0d 个应恒等的位失配了", unexpected_red);
    else if (silent_blocked != 0)
      $display("TEST FAILED: 判据 B —— %0d 个悬空位(Z)竟没失配，tb 漏检", silent_blocked);
    else if (unsel_lanes != 0)
      $display("TEST PASSED (但有已知覆盖洞: %0d 条 lane 没被选中，靠 +known_hole_frozen_select 放行)", unsel_lanes);
    else $display("TEST PASSED");
    $finish;
  end
endmodule
